INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('950377bc-faa3-57e6-9bff-b4112cc48119', 'Costa Rica Law - Regulation of the rational use', 'Law No. 7447 - Regulation of the rational use of energy', 'The purpose of this Law is to consolidate the participation of the State in the promotion and gradual execution of the program for the rational use of energy. Likewise, it is proposed to establish the mechanisms to achieve the efficient use of energy and replace them when it suits the country, considering the protection of the environment.', 'The purpose of this Law is to consolidate the participation of the State in the promotion and gradual execution of the program for the rational use of energy. Likewise, it is proposed to establish the mechanisms to achieve the efficient use of energy and replace them when it suits the country, considering the protection of the environment.', 'The purpose of this Law is to consolidate the participation of the State in the promotion and gradual execution of the program for the rational use of energy. Likewise, it is proposed to establish the mechanisms to achieve the efficient use of energy and replace them when it suits the country, considering the protection of the environment.', 'Costa Rica', 'climate', 'in_force', '1994-01-01'::date, 'Costa Rica', 'https://www.carrotsandsticks.org/policies/38_34', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'costa rica']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1b18065a-3f00-5883-8616-78b4ad57bec8', 'Croatia Act The Act on Amendments and Supplements', 'Act No. 151/25 The Act on Amendments and Supplements to the Accounting Act', 'Act No. 151/25 amends the Accounting Act in Croatia, establishing new requirements for corporate financial reporting and sustainability disclosures. It mandates that businesses subject to annual reporting must submit complete and accurate annual reports, including sustainability reports if applicable, to the Financial Agency for public disclosure. The law applies to all companies required to prepare annual financial statements and introduces specific provisions for auditors overseeing sustainability reports. This policy is mandatory and aims to enhance transparency and accountability in corporate reporting.', 'Act No. 151/25 amends the Accounting Act in Croatia, establishing new requirements for corporate financial reporting and sustainability disclosures. It mandates that businesses subject to annual reporting must submit complete and accurate annual reports, including sustainability reports if applicable, to the Financial Agency for public disclosure. The law applies to all companies required to prepare annual financial statements and introduces specific provisions for auditors overseeing sustainability reports. This policy is mandatory and aims to enhance transparency and accountability in corporate reporting.', 'Act No. 151/25 amends the Accounting Act in Croatia, establishing new requirements for corporate financial reporting and sustainability disclosures. It mandates that businesses subject to annual reporting must submit complete and accurate annual reports, including sustainability reports if applicable, to the Financial Agency for public disclosure. The law applies to all companies required to prepare annual financial statements and introduces specific provisions for auditors overseeing sustainability reports. This policy is mandatory and aims to enhance transparency and accountability in corporate reporting.', 'Croatia', 'climate', 'in_force', '2025-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_20', ARRAY['regulations', 'mandatory', 'sdg16', 'croatia', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b5b0beb9-5939-524a-9eac-20d54bd4e649', 'Croatia Act No. NN amending the Accounting Act', 'Act No. NN 126/25 amending the Accounting Act and the Capital Market Act', 'The Act No. NN 126/25 amends the Accounting Act and the Capital Market Act in Croatia, focusing on enhancing transparency and regulatory compliance in financial markets. It incorporates updates from various EU directives, particularly regarding investment firms and corporate reporting on sustainability. The amendments require investment firms to notify the regulatory agency of significant changes in their operational conditions promptly. This policy applies to all investment firms operating in Croatia and is mandatory for compliance with EU regulations.', 'The Act No. NN 126/25 amends the Accounting Act and the Capital Market Act in Croatia, focusing on enhancing transparency and regulatory compliance in financial markets. It incorporates updates from various EU directives, particularly regarding investment firms and corporate reporting on sustainability. The amendments require investment firms to notify the regulatory agency of significant changes in their operational conditions promptly. This policy applies to all investment firms operating in Croatia and is mandatory for compliance with EU regulations.', 'The Act No. NN 126/25 amends the Accounting Act and the Capital Market Act in Croatia, focusing on enhancing transparency and regulatory compliance in financial markets. It incorporates updates from various EU directives, particularly regarding investment firms and corporate reporting on sustainability. The amendments require investment firms to notify the regulatory agency of significant changes in their operational conditions promptly. This policy applies to all investment firms operating in Croatia and is mandatory for compliance with EU regulations.', 'Croatia', 'climate', 'in_force', '2025-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_21', ARRAY['regulations', 'mandatory', 'sdg16', 'croatia', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('86887699-cdcb-516e-9b45-862dc2c0eade', 'Croatia Audit Act', 'Audit Act', 'The Audit Act in Croatia, effective 2024, incorporates EU directives on financial audits. It outlines requirements for passing the audit exam, including education and work experience criteria, managed by the Croatian Chamber of Auditors.', 'The Audit Act in Croatia, effective 2024, incorporates EU directives on financial audits. It outlines requirements for passing the audit exam, including education and work experience criteria, managed by the Croatian Chamber of Auditors.', 'The Audit Act in Croatia, effective 2024, incorporates EU directives on financial audits. It outlines requirements for passing the audit exam, including education and work experience criteria, managed by the Croatian Chamber of Auditors.', 'Croatia', 'governance', 'in_force', '2024-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_13', ARRAY['sdg4', 'croatia', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ffa7ef77-4f97-5a38-abbc-9d6144abbf17', 'Croatia Capital Markets Act', 'Capital Markets Act', 'The Capital Markets Act in Croatia, updated in 2024, focuses on amending regulations related to capital market transparency and financial instrument trading. It aligns with EU directives to enhance investor protection and market integrity, impacting financial institutions, investment firms, and issuers trading on regulated markets.', 'The Capital Markets Act in Croatia, updated in 2024, focuses on amending regulations related to capital market transparency and financial instrument trading. It aligns with EU directives to enhance investor protection and market integrity, impacting financial institutions, investment firms, and issuers trading on regulated markets.', 'The Capital Markets Act in Croatia, updated in 2024, focuses on amending regulations related to capital market transparency and financial instrument trading. It aligns with EU directives to enhance investor protection and market integrity, impacting financial institutions, investment firms, and issuers trading on regulated markets.', 'Croatia', 'governance', 'in_force', '2024-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_14', ARRAY['sdg16', 'croatia', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cfb25e3a-26f7-5a49-92ce-1e4aa556ccb9', 'Croatia Corporate Governance Code', 'Corporate Governance Code', 'The Corporate Governance Code in Croatia (2024) outlines standards for responsible company management, emphasizing sustainability and resilience. It addresses leadership, board duties, risk management, transparency, and stakeholder relationships. The policy aims to improve business operations, strengthen stakeholder trust, and enhance Croatia''s capital market through regulatory cooperation and adherence to governance best practices.', 'The Corporate Governance Code in Croatia (2024) outlines standards for responsible company management, emphasizing sustainability and resilience. It addresses leadership, board duties, risk management, transparency, and stakeholder relationships. The policy aims to improve business operations, strengthen stakeholder trust, and enhance Croatia''s capital market through regulatory cooperation and adherence to governance best practices.', 'The Corporate Governance Code in Croatia (2024) outlines standards for responsible company management, emphasizing sustainability and resilience. It addresses leadership, board duties, risk management, transparency, and stakeholder relationships. The policy aims to improve business operations, strengthen stakeholder trust, and enhance Croatia''s capital market through regulatory cooperation and adherence to governance best practices.', 'Croatia', 'governance', 'in_force', '2024-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_15', ARRAY['regulations', 'sdg17', 'mandatory', 'sdg16', 'croatia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8ea02d9a-9910-593c-84b5-25be81410421', 'Croatia Accounting Act NN', 'Accounting Act NN 85/24', 'The Accounting Act NN 85/24 regulates accounting practices for entrepreneurs in Croatia, including the classification of businesses, financial reporting standards, and the requirements for annual financial statements. It mandates public interest entities to adhere to specific financial reporting and auditing standards, ensuring transparency and accountability. The law applies to all entrepreneurs, particularly those whose securities are listed on regulated markets, and incorporates several EU directives. Compliance with this act is mandatory for affected entities.', 'The Accounting Act NN 85/24 regulates accounting practices for entrepreneurs in Croatia, including the classification of businesses, financial reporting standards, and the requirements for annual financial statements. It mandates public interest entities to adhere to specific financial reporting and auditing standards, ensuring transparency and accountability. The law applies to all entrepreneurs, particularly those whose securities are listed on regulated markets, and incorporates several EU directives. Compliance with this act is mandatory for affected entities.', 'The Accounting Act NN 85/24 regulates accounting practices for entrepreneurs in Croatia, including the classification of businesses, financial reporting standards, and the requirements for annual financial statements. It mandates public interest entities to adhere to specific financial reporting and auditing standards, ensuring transparency and accountability. The law applies to all entrepreneurs, particularly those whose securities are listed on regulated markets, and incorporates several EU directives. Compliance with this act is mandatory for affected entities.', 'Croatia', 'climate', 'in_force', '2024-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_17', ARRAY['regulations', 'mandatory', 'sdg16', 'croatia', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bfb430f8-f1a9-511d-96c0-6553bfda0245', 'Croatia Act amending the Audit Act', 'Act amending the Audit Act 85/24', 'The Act amending the Audit Act 85/24 establishes mandatory public disclosure requirements for the Financial Agency and the Croatian Bank for Reconstruction and Development, effective from the business year starting January 1, 2025. It incorporates several EU directives into Croatian law, enhancing the regulatory framework for financial reporting and auditing. The act applies to entities involved in financial reporting and auditing, including authorized auditors and auditing firms, and mandates compliance with the new provisions. The purpose is to ensure transparency and accountability in financial reporting.', 'The Act amending the Audit Act 85/24 establishes mandatory public disclosure requirements for the Financial Agency and the Croatian Bank for Reconstruction and Development, effective from the business year starting January 1, 2025. It incorporates several EU directives into Croatian law, enhancing the regulatory framework for financial reporting and auditing. The act applies to entities involved in financial reporting and auditing, including authorized auditors and auditing firms, and mandates compliance with the new provisions. The purpose is to ensure transparency and accountability in financial reporting.', 'The Act amending the Audit Act 85/24 establishes mandatory public disclosure requirements for the Financial Agency and the Croatian Bank for Reconstruction and Development, effective from the business year starting January 1, 2025. It incorporates several EU directives into Croatian law, enhancing the regulatory framework for financial reporting and auditing. The act applies to entities involved in financial reporting and auditing, including authorized auditors and auditing firms, and mandates compliance with the new provisions. The purpose is to ensure transparency and accountability in financial reporting.', 'Croatia', 'climate', 'in_force', '2024-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_18', ARRAY['regulations', 'mandatory', 'sdg16', 'croatia', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('23134619-864d-5ab9-9212-7d2cc9667b04', 'Croatia Amendments to the Capital Market Act', 'Law on Amendments to the Capital Market Act 85/24', 'The Law on Amendments to the Capital Market Act 85/24 in Croatia aims to enhance the sustainability reporting framework for auditors and investment firms. It mandates that authorized auditors undergo continuous professional development in sustainability, starting from January 1, 2026. The law requires the appointment of auditing firms for sustainability reports for business years beginning on or after January 1, 2026. It applies to all investment firms and auditors involved in sustainability reporting and is part of Croatia''s compliance with EU regulations. The requirements are mandatory.', 'The Law on Amendments to the Capital Market Act 85/24 in Croatia aims to enhance the sustainability reporting framework for auditors and investment firms. It mandates that authorized auditors undergo continuous professional development in sustainability, starting from January 1, 2026. The law requires the appointment of auditing firms for sustainability reports for business years beginning on or after January 1, 2026. It applies to all investment firms and auditors involved in sustainability reporting and is part of Croatia''s compliance with EU regulations. The requirements are mandatory.', 'The Law on Amendments to the Capital Market Act 85/24 in Croatia aims to enhance the sustainability reporting framework for auditors and investment firms. It mandates that authorized auditors undergo continuous professional development in sustainability, starting from January 1, 2026. The law requires the appointment of auditing firms for sustainability reports for business years beginning on or after January 1, 2026. It applies to all investment firms and auditors involved in sustainability reporting and is part of Croatia''s compliance with EU regulations. The requirements are mandatory.', 'Croatia', 'climate', 'in_force', '2024-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_19', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'croatia', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b6175100-0b36-5ce0-93b5-27812cbb0b8f', 'Croatia Minimum Global Profit Tax', 'Law on Minimum Global Profit Tax', 'The Law on Minimum Global Profit Tax in Croatia, effective 2023, aims to ensure minimum effective taxation for multinational and domestic groups, detailing taxable subjects, calculation methods, exemptions, and reporting procedures. It aligns with the EU Council Directive 2022/2523 and applies to entities within Croatian tax jurisdiction.', 'The Law on Minimum Global Profit Tax in Croatia, effective 2023, aims to ensure minimum effective taxation for multinational and domestic groups, detailing taxable subjects, calculation methods, exemptions, and reporting procedures. It aligns with the EU Council Directive 2022/2523 and applies to entities within Croatian tax jurisdiction.', 'The Law on Minimum Global Profit Tax in Croatia, effective 2023, aims to ensure minimum effective taxation for multinational and domestic groups, detailing taxable subjects, calculation methods, exemptions, and reporting procedures. It aligns with the EU Council Directive 2022/2523 and applies to entities within Croatian tax jurisdiction.', 'Croatia', 'climate', 'in_force', '2023-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_16', ARRAY['croatia', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ddb9f3e1-5d34-5b8c-b09e-687789563eab', 'Croatia Preparation and Disclosure of ESG Relevant Issuer Information', 'Guidelines for the Preparation and Disclosure of ESG Relevant Issuer Information', 'These Guidelines are intended for issuers on the regulated market of the Republic of Croatia subject to non-financial disclosure requirements pursuant to Articles 21a and 24a of the Accounting Act, but also for those who decide to disclose non-financial statements pursuant to Article 21 of the Accounting Act on a voluntary basis.', 'These Guidelines are intended for issuers on the regulated market of the Republic of Croatia subject to non-financial disclosure requirements pursuant to Articles 21a and 24a of the Accounting Act, but also for those who decide to disclose non-financial statements pursuant to Article 21 of the Accounting Act on a voluntary basis.', 'These Guidelines are intended for issuers on the regulated market of the Republic of Croatia subject to non-financial disclosure requirements pursuant to Articles 21a and 24a of the Accounting Act, but also for those who decide to disclose non-financial statements pursuant to Article 21 of the Accounting Act on a voluntary basis.', 'Croatia', 'climate', 'in_force', '2021-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_12', ARRAY['guidance_frameworks', 'sdg13', 'sdg16', 'croatia', 'sdg12', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('24ffa84e-79de-59e0-bc17-f294fd7bb305', 'Croatian Financial Services Supervisory Agency (HANFA) - ESG Guidelines', 'Croatian Financial Services Supervisory Agency (HANFA) - ESG Guidelines', 'The Guidelines for the Preparation and Disclosure of ESG Relevant Issuer Information aim to guide issuers in Croatia on how to effectively disclose their Environmental, Social, and Governance (ESG) practices and impacts. The guidelines emphasize the importance of aligning with sustainable development goals (SDGs) and the EU Green Deal, which set the framework for achieving a climate-neutral economy by mid-century. The document highlights the growing importance of ESG factors for investors, business partners, and the financial market, encouraging transparency in non-financial reporting. Key areas for disclosure include environmental impact, human rights, governance, anti-corruption practices, and corporate social responsibility. The guidelines also discuss challenges such as preventing greenwashing and the need for harmonization of ESG standards and definitions. The goal is to ensure that ESG data disclosed by issuers is consistent, reliable, and comparable across the market.', 'The Guidelines for the Preparation and Disclosure of ESG Relevant Issuer Information aim to guide issuers in Croatia on how to effectively disclose their Environmental, Social, and Governance (ESG) practices and impacts. The guidelines emphasize the importance of aligning with sustainable development goals (SDGs) and the EU Green Deal, which set the framework for achieving a climate-neutral economy by mid-century. The document highlights the growing importance of ESG factors for investors, business partners, and the financial market, encouraging transparency in non-financial reporting. Key areas for disclosure include environmental impact, human rights, governance, anti-corruption practices, and corporate social responsibility. The guidelines also discuss challenges such as preventing greenwashing and the need for harmonization of ESG standards and definitions. The goal is to ensure that ESG data disclosed by issuers is consistent, reliable, and comparable across the market.', 'The Guidelines for the Preparation and Disclosure of ESG Relevant Issuer Information aim to guide issuers in Croatia on how to effectively disclose their Environmental, Social, and Governance (ESG) practices and impacts. The guidelines emphasize the importance of aligning with sustainable development goals (SDGs) and the EU Green Deal, which set the framework for achieving a climate-neutral economy by mid-century. The document highlights the growing importance of ESG factors for investors, business partners, and the financial market, encouraging transparency in non-financial reporting. Key areas for disclosure include environmental impact, human rights, governance, anti-corruption practices, and corporate social responsibility. The guidelines also discuss challenges such as preventing greenwashing and the need for harmonization of ESG standards and definitions. The goal is to ensure that ESG data disclosed by issuers is consistent, reliable, and comparable across the market.', 'Croatia', 'climate', 'in_force', '2021-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_6', ARRAY['guidance_frameworks', 'sdg13', 'other sustainability policy', 'sdg3', 'sdg7', 'sdg16', 'croatia', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('50785039-c010-5f94-a0d3-0e6846805f20', 'Croatia Corporate Governance Code', 'Corporate Governance Code 2019', 'The purpose of the Code is to promote effective governance and accountability in companies whose shares are admitted to trading on the regulated market of the Zagreb Stock Exchange.', 'The purpose of the Code is to promote effective governance and accountability in companies whose shares are admitted to trading on the regulated market of the Zagreb Stock Exchange.', 'The purpose of the Code is to promote effective governance and accountability in companies whose shares are admitted to trading on the regulated market of the Zagreb Stock Exchange.', 'Croatia', 'governance', 'in_force', '2019-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_11', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'croatia', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('70c64355-32c6-5b9a-a1e2-0a69c6bd82ba', 'Croatia Decision on the Promulgation of the Accounting Law', 'Decision on the Promulgation of the Accounting Law', 'This Act regulates the accounting of entrepreneurs, classification of entrepreneurs and groups of entrepreneurs, accounting documents and business books, inventory of assets and liabilities, application of financial reporting standards and the body for adopting financial reporting standards, annual financial statements and consolidation of annual financial statements, report on payments to the public sector , audit of annual financial statements and annual report, content of annual report, public announcement of annual financial statements and annual report, Register of annual financial reports and supervision.', 'This Act regulates the accounting of entrepreneurs, classification of entrepreneurs and groups of entrepreneurs, accounting documents and business books, inventory of assets and liabilities, application of financial reporting standards and the body for adopting financial reporting standards, annual financial statements and consolidation of annual financial statements, report on payments to the public sector , audit of annual financial statements and annual report, content of annual report, public announcement of annual financial statements and annual report, Register of annual financial reports and supervision.', 'This Act regulates the accounting of entrepreneurs, classification of entrepreneurs and groups of entrepreneurs, accounting documents and business books, inventory of assets and liabilities, application of financial reporting standards and the body for adopting financial reporting standards, annual financial statements and consolidation of annual financial statements, report on payments to the public sector , audit of annual financial statements and annual report, content of annual report, public announcement of annual financial statements and annual report, Register of annual financial reports and supervision.', 'Croatia', 'climate', 'in_force', '2015-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_1', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'croatia', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e487d209-29c2-51f8-9f68-8f7f793870c5', 'Croatia Register of Environmental Pollution', 'Rules on the Register of Environmental Pollution', 'This Ordinance prescribes the mandatory content and manner of keeping the register of environmental pollution (hereinafter: ROO) data subject to ROO, the manner, methodology and deadlines for collecting and submitting data on emissions or discharges, transfer and disposal of pollutants into the environment and waste, data on the polluter, plant operator, organizational unit within the polluter, deadline and manner of informing the public, manner of checking and ensuring the quality of data submitted and kept in the register, deadline for keeping records from which data were submitted, performing professional activities of ROO management and other issues team in a relationship.', 'This Ordinance prescribes the mandatory content and manner of keeping the register of environmental pollution (hereinafter: ROO) data subject to ROO, the manner, methodology and deadlines for collecting and submitting data on emissions or discharges, transfer and disposal of pollutants into the environment and waste, data on the polluter, plant operator, organizational unit within the polluter, deadline and manner of informing the public, manner of checking and ensuring the quality of data submitted and kept in the register, deadline for keeping records from which data were submitted, performing professional activities of ROO management and other issues team in a relationship.', 'This Ordinance prescribes the mandatory content and manner of keeping the register of environmental pollution (hereinafter: ROO) data subject to ROO, the manner, methodology and deadlines for collecting and submitting data on emissions or discharges, transfer and disposal of pollutants into the environment and waste, data on the polluter, plant operator, organizational unit within the polluter, deadline and manner of informing the public, manner of checking and ensuring the quality of data submitted and kept in the register, deadline for keeping records from which data were submitted, performing professional activities of ROO management and other issues team in a relationship.', 'Croatia', 'climate', 'in_force', '2015-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_5', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'sdg9', 'mandatory', 'sdg6', 'croatia', 'sdg12', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ab003696-5c4d-5d03-894c-c4099997380d', 'Croatia Decision on the Promulgation of the Law', 'Decision on the Promulgation of the Law on Sustainable Waste Management', 'This Act determines measures for the prevention or reduction of harmful effects of waste on human health and the environment by reducing the amount of waste generated and / or production and regulates waste management without the use of risky procedures for human health and the environment, using valuable properties waste.', 'This Act determines measures for the prevention or reduction of harmful effects of waste on human health and the environment by reducing the amount of waste generated and / or production and regulates waste management without the use of risky procedures for human health and the environment, using valuable properties waste.', 'This Act determines measures for the prevention or reduction of harmful effects of waste on human health and the environment by reducing the amount of waste generated and / or production and regulates waste management without the use of risky procedures for human health and the environment, using valuable properties waste.', 'Croatia', 'circularity', 'in_force', '2013-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_4', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'croatia', 'sdg12', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e026c2a2-d2ad-5251-9235-b13352ed171c', 'Croatia Decision on the Promulgation of the Law', 'Decision on the Promulgation of the Law on Air Protection', 'This Act determines the competence and responsibility for air and ozone layer protection, climate change mitigation and adaptation to climate change, planning documents, air quality monitoring and assessment, measures for prevention and reduction of air pollution, air quality reporting and data exchange, quality monitoring activity air and air emissions, ozone depleting substances and fluorinated greenhouse gases, monitoring of greenhouse gas emissions and measures for climate change mitigation and adaptation ,, air protection information system, financing of air, ozone layer protection, climate change mitigation and climate change adaptation, administrative and inspection supervision.', 'This Act determines the competence and responsibility for air and ozone layer protection, climate change mitigation and adaptation to climate change, planning documents, air quality monitoring and assessment, measures for prevention and reduction of air pollution, air quality reporting and data exchange, quality monitoring activity air and air emissions, ozone depleting substances and fluorinated greenhouse gases, monitoring of greenhouse gas emissions and measures for climate change mitigation and adaptation ,, air protection information system, financing of air, ozone layer protection, climate change mitigation and climate change adaptation, administrative and inspection supervision.', 'This Act determines the competence and responsibility for air and ozone layer protection, climate change mitigation and adaptation to climate change, planning documents, air quality monitoring and assessment, measures for prevention and reduction of air pollution, air quality reporting and data exchange, quality monitoring activity air and air emissions, ozone depleting substances and fluorinated greenhouse gases, monitoring of greenhouse gas emissions and measures for climate change mitigation and adaptation ,, air protection information system, financing of air, ozone layer protection, climate change mitigation and climate change adaptation, administrative and inspection supervision.', 'Croatia', 'climate', 'in_force', '2011-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_8', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'croatia', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4251a0f9-2de7-5eca-ba06-8ecd3b7cfc18', 'Croatia Corporate Governance Code', 'Corporate Governance Code 2009', 'The objective of this Code, representing a set of rules and principles, is to establish high standards of corporate governance and business transparency of joint stock companies for the purpose of facilitating access to capital with lower costs, with regard to the clearly defined procedures of corporate governance based on recognizable international standards being one of the basic criteria for investment decision making.', 'The objective of this Code, representing a set of rules and principles, is to establish high standards of corporate governance and business transparency of joint stock companies for the purpose of facilitating access to capital with lower costs, with regard to the clearly defined procedures of corporate governance based on recognizable international standards being one of the basic criteria for investment decision making.', 'The objective of this Code, representing a set of rules and principles, is to establish high standards of corporate governance and business transparency of joint stock companies for the purpose of facilitating access to capital with lower costs, with regard to the clearly defined procedures of corporate governance based on recognizable international standards being one of the basic criteria for investment decision making.', 'Croatia', 'governance', 'in_force', '2009-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_9', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'croatia', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ffc5abe7-653b-5691-9574-3ed00cd99490', 'Croatia Code of Corporate Governance', 'Code of Corporate Governance 2008', 'The objective of this Code is to establish high standards of corporate governance and businsess transparency in the operations of joint stock companies for the purpose of enabling easier access to capital at a lower cost, considering that clearly defined procedures of corporate governance based on recognizable international standards are among the basic criteria for investment decision-making.', 'The objective of this Code is to establish high standards of corporate governance and businsess transparency in the operations of joint stock companies for the purpose of enabling easier access to capital at a lower cost, considering that clearly defined procedures of corporate governance based on recognizable international standards are among the basic criteria for investment decision-making.', 'The objective of this Code is to establish high standards of corporate governance and businsess transparency in the operations of joint stock companies for the purpose of enabling easier access to capital at a lower cost, considering that clearly defined procedures of corporate governance based on recognizable international standards are among the basic criteria for investment decision-making.', 'Croatia', 'governance', 'in_force', '2008-01-01'::date, 'Croatia', 'https://www.carrotsandsticks.org/policies/39_10', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'croatia', 'mandatory_regulations', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cb84a1cf-e5cd-54e3-8cc9-e2e37c8004b6', 'Cyprus Companies (Amendment) Law of', 'The Companies (Amendment) Law of 2025', 'The Companies (Amendment) Law of 2025', 'The Companies (Amendment) Law of 2025', 'The Companies (Amendment) Law of 2025', 'Cyprus', 'governance', 'in_force', '2025-01-01'::date, 'Cyprus', 'https://www.carrotsandsticks.org/policies/41_11', ARRAY['cyprus', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('12746f32-b98e-5886-b0b8-cb9635453e08', 'Cyprus Transparency Requirements (Securities for Trading on a Regulated', 'The Transparency Requirements (Securities for Trading on a Regulated Market) (Amendment) Law of 2025.', 'The Transparency Requirements (Securities for Trading on a Regulated Market) (Amendment) Law of 2025 aims to align Cyprus''s regulations with European Union directives regarding sustainability reporting. It modifies existing laws to enhance transparency in financial reporting for companies trading securities on regulated markets. The law applies to all companies within this sector and establishes mandatory requirements for sustainability disclosures in accordance with EU regulations. This amendment is part of a broader effort to improve corporate governance and accountability in financial markets.', 'The Transparency Requirements (Securities for Trading on a Regulated Market) (Amendment) Law of 2025 aims to align Cyprus''s regulations with European Union directives regarding sustainability reporting. It modifies existing laws to enhance transparency in financial reporting for companies trading securities on regulated markets. The law applies to all companies within this sector and establishes mandatory requirements for sustainability disclosures in accordance with EU regulations. This amendment is part of a broader effort to improve corporate governance and accountability in financial markets.', 'The Transparency Requirements (Securities for Trading on a Regulated Market) (Amendment) Law of 2025 aims to align Cyprus''s regulations with European Union directives regarding sustainability reporting. It modifies existing laws to enhance transparency in financial reporting for companies trading securities on regulated markets. The law applies to all companies within this sector and establishes mandatory requirements for sustainability disclosures in accordance with EU regulations. This amendment is part of a broader effort to improve corporate governance and accountability in financial markets.', 'Cyprus', 'climate', 'in_force', '2025-01-01'::date, 'Cyprus', 'https://www.carrotsandsticks.org/policies/41_12', ARRAY['cyprus', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e054d076-bf48-577c-b3ce-8fa8f91b7670', 'Cyprus Law providing for the transparency requirements regarding information', 'Law providing for the transparency requirements regarding information relating to an issuer whose securities have been admitted to trading on a regulated market', 'The Cyprus law on transparency requirements for issuers with securities on a regulated market aims to ensure disclosure of financial information. It mandates annual and semi-annual reports, publicizing share ownership changes, and sets penalties for non-compliance. The policy targets issuers, investors, and regulatory authorities.', 'The Cyprus law on transparency requirements for issuers with securities on a regulated market aims to ensure disclosure of financial information. It mandates annual and semi-annual reports, publicizing share ownership changes, and sets penalties for non-compliance. The policy targets issuers, investors, and regulatory authorities.', 'The Cyprus law on transparency requirements for issuers with securities on a regulated market aims to ensure disclosure of financial information. It mandates annual and semi-annual reports, publicizing share ownership changes, and sets penalties for non-compliance. The policy targets issuers, investors, and regulatory authorities.', 'Cyprus', 'climate', 'in_force', '2025-01-01'::date, 'Cyprus', 'https://www.carrotsandsticks.org/policies/41_7', ARRAY['sdg16', 'cyprus', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('50348d83-86e7-5099-8db5-3ba69db4cfc0', 'Cyprus Companies (Amendment) () Law of', 'The Companies (Amendment) (No. 3) Law of 2025', 'The Companies (Amendment) (No. 3) Law of 2025 in Cyprus harmonizes with EU directives on sustainability reporting for companies. It amends definitions related to financial performance and market regulations. The law aims to enhance transparency and align with EU standards, impacting companies subject to financial and market regulations.', 'The Companies (Amendment) (No. 3) Law of 2025 in Cyprus harmonizes with EU directives on sustainability reporting for companies. It amends definitions related to financial performance and market regulations. The law aims to enhance transparency and align with EU standards, impacting companies subject to financial and market regulations.', 'The Companies (Amendment) (No. 3) Law of 2025 in Cyprus harmonizes with EU directives on sustainability reporting for companies. It amends definitions related to financial performance and market regulations. The law aims to enhance transparency and align with EU standards, impacting companies subject to financial and market regulations.', 'Cyprus', 'climate', 'in_force', '2025-01-01'::date, 'Cyprus', 'https://www.carrotsandsticks.org/policies/41_8', ARRAY['sdg16', 'cyprus', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0868be37-8625-50a8-9c20-2689c9deca54', 'Cyprus Auditors (Amendment) Law of', 'The Auditors (Amendment) Law of 2025', 'The Auditors (Amendment) Law of 2025 in Cyprus aims to align with EU Directive 2022/2464 for sustainability reporting and enhance auditing regulations. It introduces new terms, definitions, and obligations for auditors and audit firms to improve compliance and reporting standards. Targeting legal auditors and audit offices, it emphasizes sustainability reporting and unified financial statements.', 'The Auditors (Amendment) Law of 2025 in Cyprus aims to align with EU Directive 2022/2464 for sustainability reporting and enhance auditing regulations. It introduces new terms, definitions, and obligations for auditors and audit firms to improve compliance and reporting standards. Targeting legal auditors and audit offices, it emphasizes sustainability reporting and unified financial statements.', 'The Auditors (Amendment) Law of 2025 in Cyprus aims to align with EU Directive 2022/2464 for sustainability reporting and enhance auditing regulations. It introduces new terms, definitions, and obligations for auditors and audit firms to improve compliance and reporting standards. Targeting legal auditors and audit offices, it emphasizes sustainability reporting and unified financial statements.', 'Cyprus', 'climate', 'in_force', '2025-01-01'::date, 'Cyprus', 'https://www.carrotsandsticks.org/policies/41_9', ARRAY['cyprus', 'sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0625bc93-1f02-52de-9be1-5676fecf9266', 'Cyprus Law 51(Ι) of 2017 An Act to Amend', 'Law 51(Ι) of 2017 An Act to Amend the Companies Act', 'The Companies (Amendment) (No. 3) Act 2017 is a piece of legislation in Cyprus that amends the Companies Law. The amendment aims to enhance the corporate governance framework of companies by introducing new requirements for transparency and accountability. The key changes introduced by the Act include provisions for the registration of beneficial owners, the disclosure of significant beneficial ownership, and the establishment of a central register of beneficial ownership. The Act also introduces new requirements for the disclosure of financial statements, including the publication of audited financial statements and the submission of an annual return. Overall, the Act aims to improve the transparency and accountability of companies in Cyprus and enhance their ability to comply with international standards on anti-money laundering and countering the financing of terrorism. The Companies (Amendment) (No. 3) Act 2017 is a legal requirement for companies in Cyprus. The provisions introduced by the Act, such as the registration of beneficial owners and the disclosure of financial statements, are mandatory requirements for all companies registered in Cyprus. Failure to comply with the Act''s provisions may result in penalties or other enforcement actions by the regulatory authorities. Therefore, it is essential for companies operating in Cyprus to ensure that they are in compliance with the requirements of the Companies Law as amended by the Act.', 'The Companies (Amendment) (No. 3) Act 2017 is a piece of legislation in Cyprus that amends the Companies Law. The amendment aims to enhance the corporate governance framework of companies by introducing new requirements for transparency and accountability. The key changes introduced by the Act include provisions for the registration of beneficial owners, the disclosure of significant beneficial ownership, and the establishment of a central register of beneficial ownership. The Act also introduces new requirements for the disclosure of financial statements, including the publication of audited financial statements and the submission of an annual return. Overall, the Act aims to improve the transparency and accountability of companies in Cyprus and enhance their ability to comply with international standards on anti-money laundering and countering the financing of terrorism. The Companies (Amendment) (No. 3) Act 2017 is a legal requirement for companies in Cyprus. The provisions introduced by the Act, such as the registration of beneficial owners and the disclosure of financial statements, are mandatory requirements for all companies registered in Cyprus. Failure to comply with the Act''s provisions may result in penalties or other enforcement actions by the regulatory authorities. Therefore, it is essential for companies operating in Cyprus to ensure that they are in compliance with the requirements of the Companies Law as amended by the Act.', 'The Companies (Amendment) (No. 3) Act 2017 is a piece of legislation in Cyprus that amends the Companies Law. The amendment aims to enhance the corporate governance framework of companies by introducing new requirements for transparency and accountability. The key changes introduced by the Act include provisions for the registration of beneficial owners, the disclosure of significant beneficial ownership, and the establishment of a central register of beneficial ownership. The Act also introduces new requirements for the disclosure of financial statements, including the publication of audited financial statements and the submission of an annual return. Overall, the Act aims to improve the transparency and accountability of companies in Cyprus and enhance their ability to comply with international standards on anti-money laundering and countering the financing of terrorism. The Companies (Amendment) (No. 3) Act 2017 is a legal requirement for companies in Cyprus. The provisions introduced by the Act, such as the registration of beneficial owners and the disclosure of financial statements, are mandatory requirements for all companies registered in Cyprus. Failure to comply with the Act''s provisions may result in penalties or other enforcement actions by the regulatory authorities. Therefore, it is essential for companies operating in Cyprus to ensure that they are in compliance with the requirements of the Companies Law as amended by the Act.', 'Cyprus', 'governance', 'in_force', '2017-01-01'::date, 'Cyprus', 'https://www.carrotsandsticks.org/policies/41_6', ARRAY['cyprus', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5e73f039-ae79-5784-8272-5e1f6d1f0422', 'Cyprus Stock Exchange Corporate Governance Code', 'Cyprus Stock Exchange Corporate Governance Code 4th edition', 'This is the 4th edition of the Cyprus Corporate Governance Code which includes proposed regulations that aim to strengthen the monitoring role of the Board of Directors in listed companies, protect small shareholders, adopt greater transparency and provide timely information as well as sufficiently safeguard the independence of the Board of Directors in its decision-making.', 'This is the 4th edition of the Cyprus Corporate Governance Code which includes proposed regulations that aim to strengthen the monitoring role of the Board of Directors in listed companies, protect small shareholders, adopt greater transparency and provide timely information as well as sufficiently safeguard the independence of the Board of Directors in its decision-making.', 'This is the 4th edition of the Cyprus Corporate Governance Code which includes proposed regulations that aim to strengthen the monitoring role of the Board of Directors in listed companies, protect small shareholders, adopt greater transparency and provide timely information as well as sufficiently safeguard the independence of the Board of Directors in its decision-making.', 'Cyprus', 'governance', 'in_force', '2014-01-01'::date, 'Cyprus', 'https://www.carrotsandsticks.org/policies/41_3', ARRAY['cyprus', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('90ab9f17-6d61-5f87-91a3-600f67d0146a', 'Cyprus National Action Plan for Corporate Social Responsibility', 'National Action Plan for Corporate Social Responsibility', 'The government developed the National Action Plan (NAP) to promote, in a coordinated manner, the concept of Corporate Social Responsibility (CSR) in Cyprus, to encourage responsible entrepreneurship and to motivate companies to take into account the impact of their activities on society. The main objective is to increase the number of Cypriot enterprises engaged in CSR and raise awareness that CSR does not concern only large enterprises – the goal is to make obvious that even the smallest companies can take actions that promote responsible entrepreneurship, limiting the negative impact on society, achieving a balance between profitability and sustainable growth.', 'The government developed the National Action Plan (NAP) to promote, in a coordinated manner, the concept of Corporate Social Responsibility (CSR) in Cyprus, to encourage responsible entrepreneurship and to motivate companies to take into account the impact of their activities on society. The main objective is to increase the number of Cypriot enterprises engaged in CSR and raise awareness that CSR does not concern only large enterprises – the goal is to make obvious that even the smallest companies can take actions that promote responsible entrepreneurship, limiting the negative impact on society, achieving a balance between profitability and sustainable growth.', 'The government developed the National Action Plan (NAP) to promote, in a coordinated manner, the concept of Corporate Social Responsibility (CSR) in Cyprus, to encourage responsible entrepreneurship and to motivate companies to take into account the impact of their activities on society. The main objective is to increase the number of Cypriot enterprises engaged in CSR and raise awareness that CSR does not concern only large enterprises – the goal is to make obvious that even the smallest companies can take actions that promote responsible entrepreneurship, limiting the negative impact on society, achieving a balance between profitability and sustainable growth.', 'Cyprus', 'climate', 'in_force', '2013-01-01'::date, 'Cyprus', 'https://www.carrotsandsticks.org/policies/41_2', ARRAY['cyprus', 'sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
