INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('59714172-2f0a-5f84-b283-a69039ef12f1', 'Czechia Act Coll', 'Act No. 316/2025 Coll.', 'Act No. 316/2025 Coll. in the Czech Republic amends accounting and auditing laws, and tax regulations for large multinational and domestic groups. It sets new financial thresholds and reporting requirements aimed at businesses meeting specific criteria for size and public interest.', 'Act No. 316/2025 Coll. in the Czech Republic amends accounting and auditing laws, and tax regulations for large multinational and domestic groups. It sets new financial thresholds and reporting requirements aimed at businesses meeting specific criteria for size and public interest.', 'Act No. 316/2025 Coll. in the Czech Republic amends accounting and auditing laws, and tax regulations for large multinational and domestic groups. It sets new financial thresholds and reporting requirements aimed at businesses meeting specific criteria for size and public interest.', 'Czechia', 'climate', 'in_force', '2025-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_20', ARRAY['czechia', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cce2d717-7eb0-5476-a4bf-859ae95ba7fa', 'Czechia Act Coll., amending certain laws in the field', 'Act No. 317/2025 Coll., amending certain laws in the field of the financial market in connection with the establishment and operation of a single European access point', 'Act No. 317/2025 in the Czech Republic amends financial market laws to establish a single European access point. It mandates disclosure of sustainability reports, financial documents, and audit reports to the Czech National Bank for central access through this platform. Targeted at financial entities required to publish these documents.', 'Act No. 317/2025 in the Czech Republic amends financial market laws to establish a single European access point. It mandates disclosure of sustainability reports, financial documents, and audit reports to the Czech National Bank for central access through this platform. Targeted at financial entities required to publish these documents.', 'Act No. 317/2025 in the Czech Republic amends financial market laws to establish a single European access point. It mandates disclosure of sustainability reports, financial documents, and audit reports to the Czech National Bank for central access through this platform. Targeted at financial entities required to publish these documents.', 'Czechia', 'climate', 'in_force', '2025-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_24', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'czechia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('72460880-f0ff-5deb-986d-1753fd78e190', 'Czechia Sustainability Reporting Guidelines. Promoting better corporate practices', 'Sustainability Reporting Guidelines. Promoting better corporate practices in response to growing market expectations by enhancing environmental, social and governance (ESG) reporting in the Czech Republic', 'The aim of these Guidelines is to help companies in the Czech Republic to navigate through the new regulatory package on ESG reporting (CSRD, Taxonomy, SFDR, CSDDD) and understand their obligations under the first European Sustainability Reporting Standards (ESRS), in the context of a global shift towards transparency in ESG.', 'The aim of these Guidelines is to help companies in the Czech Republic to navigate through the new regulatory package on ESG reporting (CSRD, Taxonomy, SFDR, CSDDD) and understand their obligations under the first European Sustainability Reporting Standards (ESRS), in the context of a global shift towards transparency in ESG.', 'The aim of these Guidelines is to help companies in the Czech Republic to navigate through the new regulatory package on ESG reporting (CSRD, Taxonomy, SFDR, CSDDD) and understand their obligations under the first European Sustainability Reporting Standards (ESRS), in the context of a global shift towards transparency in ESG.', 'Czechia', 'climate', 'in_force', '2023-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_19', ARRAY['regulations', 'sdg7', 'sdg16', 'disclosure', 'czechia', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ef616ff5-6f2f-5a3e-b8c7-6c479383bd65', 'Czechia Collection of Laws /', 'Collection of Laws No. 416 / 2023', 'Czech Republic''s Collection of Laws No. 416/2023 addresses transfer pricing for large multinational and national groups. It aligns with OECD guidelines to prevent tax base erosion globally. The policy defines terms and establishes rules for calculating and applying transfer pricing adjustments, targeting entities within the Czech Republic.', 'Czech Republic''s Collection of Laws No. 416/2023 addresses transfer pricing for large multinational and national groups. It aligns with OECD guidelines to prevent tax base erosion globally. The policy defines terms and establishes rules for calculating and applying transfer pricing adjustments, targeting entities within the Czech Republic.', 'Czech Republic''s Collection of Laws No. 416/2023 addresses transfer pricing for large multinational and national groups. It aligns with OECD guidelines to prevent tax base erosion globally. The policy defines terms and establishes rules for calculating and applying transfer pricing adjustments, targeting entities within the Czech Republic.', 'Czechia', 'governance', 'in_force', '2023-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_21', ARRAY['czechia', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4eec1f07-c165-5d15-b563-a32ebdeb0f79', 'Czechia Czech National Energy and Climate Plan (NECP)', 'Czech National Energy and Climate Plan (NECP)', 'The National Energy and Climate Plan (NECP) of the Czech Republic, prepared in compliance with EU regulations, outlines the country''s energy and climate goals for the period 2021–2030 and provides a pathway for achieving a low-carbon economy by 2050. The plan addresses five key dimensions of the Energy Union: decarbonization, energy efficiency, energy security, the internal energy market, and research, innovation, and competitiveness. It sets specific targets for reducing greenhouse gas emissions, increasing the share of renewable energy sources, and improving energy efficiency. The Czech Republic aims to reduce emissions by 30% by 2030 compared to 2005 levels and proposes a 22% share of renewable energy in gross final consumption by 2030. The plan also emphasizes the importance of energy security and infrastructure development, aiming to maintain a competitive energy market while ensuring a sustainable energy supply.', 'The National Energy and Climate Plan (NECP) of the Czech Republic, prepared in compliance with EU regulations, outlines the country''s energy and climate goals for the period 2021–2030 and provides a pathway for achieving a low-carbon economy by 2050. The plan addresses five key dimensions of the Energy Union: decarbonization, energy efficiency, energy security, the internal energy market, and research, innovation, and competitiveness. It sets specific targets for reducing greenhouse gas emissions, increasing the share of renewable energy sources, and improving energy efficiency. The Czech Republic aims to reduce emissions by 30% by 2030 compared to 2005 levels and proposes a 22% share of renewable energy in gross final consumption by 2030. The plan also emphasizes the importance of energy security and infrastructure development, aiming to maintain a competitive energy market while ensuring a sustainable energy supply.', 'The National Energy and Climate Plan (NECP) of the Czech Republic, prepared in compliance with EU regulations, outlines the country''s energy and climate goals for the period 2021–2030 and provides a pathway for achieving a low-carbon economy by 2050. The plan addresses five key dimensions of the Energy Union: decarbonization, energy efficiency, energy security, the internal energy market, and research, innovation, and competitiveness. It sets specific targets for reducing greenhouse gas emissions, increasing the share of renewable energy sources, and improving energy efficiency. The Czech Republic aims to reduce emissions by 30% by 2030 compared to 2005 levels and proposes a 22% share of renewable energy in gross final consumption by 2030. The plan also emphasizes the importance of energy security and infrastructure development, aiming to maintain a competitive energy market while ensuring a sustainable energy supply.', 'Czechia', 'climate', 'in_force', '2020-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_2', ARRAY['sdg13', 'sdg14', 'sdg7', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'czechia', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4ee3b445-f163-5597-a1f6-ffc66873021e', 'Czechia 542 Act of 1 December 2020 on end-of-life', '542 Act of 1 December 2020 on end-of-life products', 'The 542 Act of 1 December 2020 on end-of-life products in the Czech Republic aims to regulate waste prevention, producer responsibilities, and administrative oversight for selected products. It covers a wide range of products and activities related to waste management and environmental protection, targeting manufacturers, consumers, and regulatory authorities.', 'The 542 Act of 1 December 2020 on end-of-life products in the Czech Republic aims to regulate waste prevention, producer responsibilities, and administrative oversight for selected products. It covers a wide range of products and activities related to waste management and environmental protection, targeting manufacturers, consumers, and regulatory authorities.', 'The 542 Act of 1 December 2020 on end-of-life products in the Czech Republic aims to regulate waste prevention, producer responsibilities, and administrative oversight for selected products. It covers a wide range of products and activities related to waste management and environmental protection, targeting manufacturers, consumers, and regulatory authorities.', 'Czechia', 'circularity', 'in_force', '2020-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_22', ARRAY['czechia', 'mandatory', 'sdg12', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('308c7027-42ae-5a1d-b68b-d3fe5cae5389', 'Czechia Waste Act ( Coll.)', 'Waste Act (No. 541/2020 Coll.)', 'The Waste Act (No. 541/2020 Coll.) in the Czech Republic aims to protect the environment and public health by managing waste sustainably. It establishes rules for waste prevention, handling, and the responsibilities of waste management entities, aligning with EU regulations while transitioning towards a circular economy. Targeted at waste management authorities and stakeholders.', 'The Waste Act (No. 541/2020 Coll.) in the Czech Republic aims to protect the environment and public health by managing waste sustainably. It establishes rules for waste prevention, handling, and the responsibilities of waste management entities, aligning with EU regulations while transitioning towards a circular economy. Targeted at waste management authorities and stakeholders.', 'The Waste Act (No. 541/2020 Coll.) in the Czech Republic aims to protect the environment and public health by managing waste sustainably. It establishes rules for waste prevention, handling, and the responsibilities of waste management entities, aligning with EU regulations while transitioning towards a circular economy. Targeted at waste management authorities and stakeholders.', 'Czechia', 'circularity', 'in_force', '2020-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_23', ARRAY['regulations', 'mandatory', 'sdg12', 'czechia', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1aec9355-d438-57e5-bf02-aaba558d35a4', 'Czechia National Action Plan for Corporate Social Responsibility', 'National Action Plan for Corporate Social Responsibility (2019-2023)', 'The action plan identifies good practices, national and international CSR development mapping and operation strategy to promote the implementation of CSR.', 'The action plan identifies good practices, national and international CSR development mapping and operation strategy to promote the implementation of CSR.', 'The action plan identifies good practices, national and international CSR development mapping and operation strategy to promote the implementation of CSR.', 'Czechia', 'governance', 'in_force', '2018-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_3', ARRAY['sdg4', 'other sustainability policy', 'regulations', 'mandatory', 'czechia', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b872a1aa-617b-5c6e-bbd4-da7e70dbbe10', 'Czechia Act of 2 May 2012 on air protection', 'Act of 2 May 2012 on air protection', 'This Act defines objectives for ambient air quality: air protection, the prevention of air pollution and reducing the level of pollution in order to reduce the risks to human health caused by air pollution, reduce the level of substances damaging ecosystems and create conditions for the regeneration of the environment affected due to pollution air. This Act implements the relevant European Union regulations and defines: (a) permitted levels of pollution and air pollution; (b) method of assessing acceptable levels of pollution and air pollution; (c) measures to reduce pollution and air pollution; (d) rights and obligations of persons and the competence of public administration at the air protection; (e) rights and obligations of public authorities to monitor and reduce greenhouse gas emissions from transport fuels. The present Act consists of 44 articles divided into the following Sections: (1) Introductory provisions; (2) Pollution; (3) Measures to reduce pollution; (4) Obligations of persons and sustainability criteria for biofuels; (5) Remedial measures and administrative offences; (6) State administration; (7) Transitional regime for combustion plants; (8) Common and transitional provisions; (9) Entry into force.', 'This Act defines objectives for ambient air quality: air protection, the prevention of air pollution and reducing the level of pollution in order to reduce the risks to human health caused by air pollution, reduce the level of substances damaging ecosystems and create conditions for the regeneration of the environment affected due to pollution air. This Act implements the relevant European Union regulations and defines: (a) permitted levels of pollution and air pollution; (b) method of assessing acceptable levels of pollution and air pollution; (c) measures to reduce pollution and air pollution; (d) rights and obligations of persons and the competence of public administration at the air protection; (e) rights and obligations of public authorities to monitor and reduce greenhouse gas emissions from transport fuels. The present Act consists of 44 articles divided into the following Sections: (1) Introductory provisions; (2) Pollution; (3) Measures to reduce pollution; (4) Obligations of persons and sustainability criteria for biofuels; (5) Remedial measures and administrative offences; (6) State administration; (7) Transitional regime for combustion plants; (8) Common and transitional provisions; (9) Entry into force.', 'This Act defines objectives for ambient air quality: air protection, the prevention of air pollution and reducing the level of pollution in order to reduce the risks to human health caused by air pollution, reduce the level of substances damaging ecosystems and create conditions for the regeneration of the environment affected due to pollution air. This Act implements the relevant European Union regulations and defines: (a) permitted levels of pollution and air pollution; (b) method of assessing acceptable levels of pollution and air pollution; (c) measures to reduce pollution and air pollution; (d) rights and obligations of persons and the competence of public administration at the air protection; (e) rights and obligations of public authorities to monitor and reduce greenhouse gas emissions from transport fuels. The present Act consists of 44 articles divided into the following Sections: (1) Introductory provisions; (2) Pollution; (3) Measures to reduce pollution; (4) Obligations of persons and sustainability criteria for biofuels; (5) Remedial measures and administrative offences; (6) State administration; (7) Transitional regime for combustion plants; (8) Common and transitional provisions; (9) Entry into force.', 'Czechia', 'climate', 'in_force', '2012-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_6', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg6', 'sdg12', 'disclosure', 'czechia', 'sdg15', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8d948b1a-343d-5485-9df8-7d4ee521f65a', 'Czechia Auditors', 'Act on Auditors No 93/2009', 'The Czech Republic''s Act No. 93/2009 on Auditors establishes the regulation of auditors and audit companies. The Act requires all businesses to have their financial statements audited, and outlines the requirements for auditors and audit companies. It also includes provisions for auditor independence, liability, and quality control. Additionally, the Act establishes the Czech Chamber of Auditors, which is responsible for the oversight and regulation of auditors and audit companies in the country.', 'The Czech Republic''s Act No. 93/2009 on Auditors establishes the regulation of auditors and audit companies. The Act requires all businesses to have their financial statements audited, and outlines the requirements for auditors and audit companies. It also includes provisions for auditor independence, liability, and quality control. Additionally, the Act establishes the Czech Chamber of Auditors, which is responsible for the oversight and regulation of auditors and audit companies in the country.', 'The Czech Republic''s Act No. 93/2009 on Auditors establishes the regulation of auditors and audit companies. The Act requires all businesses to have their financial statements audited, and outlines the requirements for auditors and audit companies. It also includes provisions for auditor independence, liability, and quality control. Additionally, the Act establishes the Czech Chamber of Auditors, which is responsible for the oversight and regulation of auditors and audit companies in the country.', 'Czechia', 'governance', 'in_force', '2009-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_4', ARRAY['czechia', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eacae278-b76d-5148-901d-d01438fe220c', 'Czechia Government Regulation Coll. establishing a list of pollutants', 'Government Regulation No. 145/2008 Coll. establishing a list of pollutants and threshold values and data required for reporting to the integrated environmental pollution register', 'The 2008 Regulation of the Czech Republic No. 145/2008 Sb. establishes a list of pollutants and threshold values as well as the data required for reporting to the Integrated Register of Environmental Pollution. The obligations of businesses under this regulation include the obligation to report emissions and releases of pollutants to the Integrated Register, to measure and monitor emissions and releases, and to comply with the threshold values established for each pollutant. The regulation also requires businesses to maintain records and documentation related to their emissions and releases of pollutants.', 'The 2008 Regulation of the Czech Republic No. 145/2008 Sb. establishes a list of pollutants and threshold values as well as the data required for reporting to the Integrated Register of Environmental Pollution. The obligations of businesses under this regulation include the obligation to report emissions and releases of pollutants to the Integrated Register, to measure and monitor emissions and releases, and to comply with the threshold values established for each pollutant. The regulation also requires businesses to maintain records and documentation related to their emissions and releases of pollutants.', 'The 2008 Regulation of the Czech Republic No. 145/2008 Sb. establishes a list of pollutants and threshold values as well as the data required for reporting to the Integrated Register of Environmental Pollution. The obligations of businesses under this regulation include the obligation to report emissions and releases of pollutants to the Integrated Register, to measure and monitor emissions and releases, and to comply with the threshold values established for each pollutant. The regulation also requires businesses to maintain records and documentation related to their emissions and releases of pollutants.', 'Czechia', 'climate', 'in_force', '2008-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_18', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'sdg12', 'disclosure', 'czechia', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4931c3d8-a1a2-52d2-ad54-9afa4aaed908', 'Czechia Corporate Governance Code based on the OECD Principles', 'Corporate Governance Code based on the OECD Principles, 2004', 'The Code is primarily based on the OECD Principles of Corporate Governance (2004) and is intended predominantly for companies whose securities are listed on the Stock Exchange, although other companies are encouraged to apply it as well.', 'The Code is primarily based on the OECD Principles of Corporate Governance (2004) and is intended predominantly for companies whose securities are listed on the Stock Exchange, although other companies are encouraged to apply it as well.', 'The Code is primarily based on the OECD Principles of Corporate Governance (2004) and is intended predominantly for companies whose securities are listed on the Stock Exchange, although other companies are encouraged to apply it as well.', 'Czechia', 'climate', 'in_force', '2004-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_1', ARRAY['guidance_frameworks', 'sdg7', 'sdg16', 'disclosure', 'czechia', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a26a0838-89e2-5b38-98c7-4efd8c70b81c', 'Czechia Act Coll. On Capital Market Business', 'Act No. 256/2004 Coll. On Capital Market Business', 'This Act incorporates the relevant regulations of the European Union, at the same time follows the directly applicable regulations of the European Union and regulates the provision of services in the area of the capital market and the protection of the capital market and investors.  This Act also incorporates the relevant regulations of the European Union regulating the final settlement and regulates the legal regime of the final settlement.', 'This Act incorporates the relevant regulations of the European Union, at the same time follows the directly applicable regulations of the European Union and regulates the provision of services in the area of the capital market and the protection of the capital market and investors.  This Act also incorporates the relevant regulations of the European Union regulating the final settlement and regulates the legal regime of the final settlement.', 'This Act incorporates the relevant regulations of the European Union, at the same time follows the directly applicable regulations of the European Union and regulates the provision of services in the area of the capital market and the protection of the capital market and investors.  This Act also incorporates the relevant regulations of the European Union regulating the final settlement and regulates the legal regime of the final settlement.', 'Czechia', 'governance', 'in_force', '2004-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_12', ARRAY['czechia', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8dc29755-f28f-59fd-9b3a-151f5f6e117e', 'Czechia Act Coll. The Act on integrated prevention', 'Act No 76 Coll. The Act on integrated prevention', 'The purpose of this Act is, in accordance with the legislation of the European Communities, to achieve a high level of protection of the environment as a whole, to provide for integrated implementation of the public administration in permitting the operation of installations and to create and operate an integrated pollution register. The Act: a) lays down the obligations of operators of installations, b) establishes the procedure for granting an integrated permit, c) establishes the integrated pollution register, and lays down the manner of collecting information on emissions and transfers of substances registered in this register and the provision of data therefrom, d) provides for conditions for interconnection of existing information systems in the area of environmental protection with the integrated pollution register, e) sets competences of public administration bodies pursuant to this Act, f) establishes the system for exchange of information on the best available techniques, g) lays down sanctions for breach of obligations laid down by this Act. The main part of the Act (Part One) is divided into 7 Chapters: Introductory Provisions (I); Integrated Decision-Making (II); Integrated Pollution Register (III); Systems for Exchange of Information on the Best available techniques (IV); Execution of the Public Administration (V); Fines (VI); Transitory, Concluding and Enabling Provisions Transitory Provisions (VII).', 'The purpose of this Act is, in accordance with the legislation of the European Communities, to achieve a high level of protection of the environment as a whole, to provide for integrated implementation of the public administration in permitting the operation of installations and to create and operate an integrated pollution register. The Act: a) lays down the obligations of operators of installations, b) establishes the procedure for granting an integrated permit, c) establishes the integrated pollution register, and lays down the manner of collecting information on emissions and transfers of substances registered in this register and the provision of data therefrom, d) provides for conditions for interconnection of existing information systems in the area of environmental protection with the integrated pollution register, e) sets competences of public administration bodies pursuant to this Act, f) establishes the system for exchange of information on the best available techniques, g) lays down sanctions for breach of obligations laid down by this Act. The main part of the Act (Part One) is divided into 7 Chapters: Introductory Provisions (I); Integrated Decision-Making (II); Integrated Pollution Register (III); Systems for Exchange of Information on the Best available techniques (IV); Execution of the Public Administration (V); Fines (VI); Transitory, Concluding and Enabling Provisions Transitory Provisions (VII).', 'The purpose of this Act is, in accordance with the legislation of the European Communities, to achieve a high level of protection of the environment as a whole, to provide for integrated implementation of the public administration in permitting the operation of installations and to create and operate an integrated pollution register. The Act: a) lays down the obligations of operators of installations, b) establishes the procedure for granting an integrated permit, c) establishes the integrated pollution register, and lays down the manner of collecting information on emissions and transfers of substances registered in this register and the provision of data therefrom, d) provides for conditions for interconnection of existing information systems in the area of environmental protection with the integrated pollution register, e) sets competences of public administration bodies pursuant to this Act, f) establishes the system for exchange of information on the best available techniques, g) lays down sanctions for breach of obligations laid down by this Act. The main part of the Act (Part One) is divided into 7 Chapters: Introductory Provisions (I); Integrated Decision-Making (II); Integrated Pollution Register (III); Systems for Exchange of Information on the Best available techniques (IV); Execution of the Public Administration (V); Fines (VI); Transitory, Concluding and Enabling Provisions Transitory Provisions (VII).', 'Czechia', 'climate', 'in_force', '2002-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_11', ARRAY['sdg13', 'regulations', 'mandatory', 'disclosure', 'czechia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e8137c17-4a6b-5df7-ac45-ded9b07146d5', 'Czechia Waste and Amendment on Some Other Acts', 'Act No 185 on Waste and Amendment on Some Other Acts', 'The 185/2001 Sb. Zákon o odpadech (Waste Act) of the Czech Republic imposes obligations on businesses regarding the handling and disposal of waste. The law requires businesses to follow waste management plans, obtain permits for waste disposal, and properly classify and label waste. Businesses are also required to keep records of their waste disposal activities and to ensure that their waste does not harm the environment or public health. Additionally, the law requires businesses to participate in recycling programs and to reduce waste through waste prevention and recycling initiatives. Non-compliance with the law can result in fines and other penalties.', 'The 185/2001 Sb. Zákon o odpadech (Waste Act) of the Czech Republic imposes obligations on businesses regarding the handling and disposal of waste. The law requires businesses to follow waste management plans, obtain permits for waste disposal, and properly classify and label waste. Businesses are also required to keep records of their waste disposal activities and to ensure that their waste does not harm the environment or public health. Additionally, the law requires businesses to participate in recycling programs and to reduce waste through waste prevention and recycling initiatives. Non-compliance with the law can result in fines and other penalties.', 'The 185/2001 Sb. Zákon o odpadech (Waste Act) of the Czech Republic imposes obligations on businesses regarding the handling and disposal of waste. The law requires businesses to follow waste management plans, obtain permits for waste disposal, and properly classify and label waste. Businesses are also required to keep records of their waste disposal activities and to ensure that their waste does not harm the environment or public health. Additionally, the law requires businesses to participate in recycling programs and to reduce waste through waste prevention and recycling initiatives. Non-compliance with the law can result in fines and other penalties.', 'Czechia', 'climate', 'in_force', '2001-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_14', ARRAY['regulations', 'sdg7', 'mandatory', 'sdg12', 'disclosure', 'czechia', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('56d8fd20-1547-5c97-a18e-f8eda0da5b2b', 'Czechia Act Coll. (Water Act)', 'Act No. 254/2001 Coll. (Water Act)', 'The 2001 Water Act is the overarching law for the protection and management of water resources. It includes provisions for water conservation, flood prevention, economic instruments for water management, and water planning and international co-operation. It also regulates water discharge permits.', 'The 2001 Water Act is the overarching law for the protection and management of water resources. It includes provisions for water conservation, flood prevention, economic instruments for water management, and water planning and international co-operation. It also regulates water discharge permits.', 'The 2001 Water Act is the overarching law for the protection and management of water resources. It includes provisions for water conservation, flood prevention, economic instruments for water management, and water planning and international co-operation. It also regulates water discharge permits.', 'Czechia', 'climate', 'in_force', '2001-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_15', ARRAY['regulations', 'sdg7', 'mandatory', 'sdg6', 'disclosure', 'czechia', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('05980c1c-b8b6-5384-b364-211da6b4be3d', 'Czechia Decree Coll. on the details of waste management', 'Decree No. 383/2001 Coll. on the details of waste management', 'The Czech Republic''s Vyhláška č. 383/2001 Sb. is a regulation that defines the conditions for waste management, including the collection, transport, storage, disposal, and utilization of waste. It applies to all waste producers, including businesses. The regulation stipulates that businesses are responsible for managing their waste in accordance with the principles of waste management, including waste prevention, reuse, and recycling. Additionally, businesses must ensure that waste is collected, transported, and disposed of by authorized waste management companies and in accordance with relevant environmental laws and regulations. The regulation also includes provisions for monitoring and reporting on waste management activities.', 'The Czech Republic''s Vyhláška č. 383/2001 Sb. is a regulation that defines the conditions for waste management, including the collection, transport, storage, disposal, and utilization of waste. It applies to all waste producers, including businesses. The regulation stipulates that businesses are responsible for managing their waste in accordance with the principles of waste management, including waste prevention, reuse, and recycling. Additionally, businesses must ensure that waste is collected, transported, and disposed of by authorized waste management companies and in accordance with relevant environmental laws and regulations. The regulation also includes provisions for monitoring and reporting on waste management activities.', 'The Czech Republic''s Vyhláška č. 383/2001 Sb. is a regulation that defines the conditions for waste management, including the collection, transport, storage, disposal, and utilization of waste. It applies to all waste producers, including businesses. The regulation stipulates that businesses are responsible for managing their waste in accordance with the principles of waste management, including waste prevention, reuse, and recycling. Additionally, businesses must ensure that waste is collected, transported, and disposed of by authorized waste management companies and in accordance with relevant environmental laws and regulations. The regulation also includes provisions for monitoring and reporting on waste management activities.', 'Czechia', 'climate', 'in_force', '2001-01-01'::date, 'Czech Republic', 'https://www.carrotsandsticks.org/policies/42_17', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'sdg12', 'czechia']::text[]) ON CONFLICT (id) DO NOTHING;
